&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Matrone &#226;g&#233;e troll&lt;div style=&quot;float:right;&quot;&gt;FP 10&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Humano&#239;de&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Humano&#239;de.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Montagnes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Montagnes.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Froid&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Froid.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Codex monstrueux p.230&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;XP&lt;/b&gt; 9600
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Troll.html&quot; title=&quot;Troll&quot;&gt;Troll&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;sorci&#232;re&lt;/a&gt; 10 (&lt;i&gt;Manuel des Joueurs, r&#232;gles avanc&#233;es&lt;/i&gt; p. 65)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-G&#233;ant.html&quot; title=&quot;G&#233;ant (sous-type)&quot;&gt;g&#233;ant&lt;/a&gt;) de taille G, CM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +6 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Odorat-(Capacit&#233;).html&quot; title=&quot;odorat&quot;&gt;odorat&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; 18 m (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;vision nocturne&quot;&gt;vision nocturne&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +16
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 18, contact 11, pris au d&#233;pourvu 16 (+2 armure, +2 Dex, +5 naturelle, -1 taille)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 200 (16 DV ; 6d8+10d6+138) ; r&#233;g&#233;n&#233;ration 5 (acide ou feu)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +8, &lt;b&gt;Vig&lt;/b&gt; +17, &lt;b&gt;Vol&lt;/b&gt; +12
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +12 (1d8+4) et 2 griffes, +12 (1d6+4)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Espace&lt;/b&gt; 3 m (2 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) ; &lt;b&gt;Allonge&lt;/b&gt; 3 m (2 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;&#201;ventration-(Capacit&#233;).html&quot; title=&quot;&#201;ventration&quot;&gt;&#233;ventration&lt;/a&gt; (2 griffes, 1d6+7)), &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#MALEFICE&quot; title=&quot;La sorci&#232;re&quot;&gt;mal&#233;fices&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Agonie&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;agonie&lt;/a&gt; (10 rounds) &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Mauvaisœil&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;mauvais œil&lt;/a&gt; (-4, 6 rounds), &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Malchance&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;malchance&lt;/a&gt; (2 rounds), &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Poumonaquatique&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;poumon aquatique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Ricanement&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;ricanement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Sommeil&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;sommeil&lt;/a&gt; (10 rounds))
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Sorts de sorci&#232;re pr&#233;par&#233;s&lt;/b&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 10 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +13)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
5e – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Colonne-De-Feu.html&quot; title=&quot;Colonne de feu&quot;&gt;colonne de feu&lt;/a&gt;&lt;/i&gt; (DD 20), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Frappe-Douloureuse-De-Groupe.html&quot; title=&quot;Frappe douloureuse de groupe&quot;&gt;frappe douloureuse de groupe&lt;/a&gt;&lt;/i&gt; (DD 18)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
4e – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Confusion.html&quot; title=&quot;Confusion&quot;&gt;confusion&lt;/a&gt;&lt;/i&gt; (DD 17), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;nergie-N&#233;gative.html&quot; title=&quot;&#201;nergie n&#233;gative&quot;&gt;&#233;nergie n&#233;gative&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mur-De-Glace.html&quot; title=&quot;Mur de glace&quot;&gt;mur de glace&lt;/a&gt;&lt;/i&gt; (DD 17)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
3e – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Boule-De-Feu.html&quot; title=&quot;Boule de feu&quot;&gt;boule de feu&lt;/a&gt;&lt;/i&gt; (2, DD 18), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cri-Strident.html&quot; title=&quot;Cri strident&quot;&gt;cri strident&lt;/a&gt;&lt;/i&gt; (DD 16), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rayon-D&#233;puisement.html&quot; title=&quot;Rayon d&amp;#39;&#233;puisement&quot;&gt;rayon d’&#233;puisement&lt;/a&gt;&lt;/i&gt; (DD 16)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
2e – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Discours-Captivant.html&quot; title=&quot;Discours captivant&quot;&gt;discours captivant&lt;/a&gt;&lt;/i&gt; (DD 15), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Force-De-Taureau.html&quot; title=&quot;Force de taureau&quot;&gt;force de taureau&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Idiotie.html&quot; title=&quot;Idiotie&quot;&gt;idiotie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Regard-Br&#251;lant.html&quot; title=&quot;Regard br&#251;lant&quot;&gt;regard br&#251;lant&lt;/a&gt;&lt;/i&gt; (DD 17), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sph&#232;re-De-Feu.html&quot; title=&quot;Sph&#232;re de feu&quot;&gt;sph&#232;re de feu&lt;/a&gt;&lt;/i&gt; (DD 17)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1er – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Frayeur.html&quot; title=&quot;Frayeur&quot;&gt;frayeur&lt;/a&gt;&lt;/i&gt; (DD 14), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mains-Br&#251;lantes.html&quot; title=&quot;Mains br&#251;lantes&quot;&gt;mains br&#251;lantes&lt;/a&gt;&lt;/i&gt; (DD 16), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rapetissement.html&quot; title=&quot;Rapetissement&quot;&gt;rapetissement&lt;/a&gt;&lt;/i&gt; (DD 14), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rayon-Affaiblissant.html&quot; title=&quot;Rayon affaiblissant&quot;&gt;rayon affaiblissant&lt;/a&gt;&lt;/i&gt; (DD 14)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
0 (&#224; volont&#233;) – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fatigue.html&quot; title=&quot;Fatigue&quot;&gt;fatigue&lt;/a&gt;&lt;/i&gt; (DD 13), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Purification-De-Nourriture-Et-Deau.html&quot; title=&quot;Purification de nourriture et d&amp;#39;eau&quot;&gt;purification de la nourriture et de l’eau&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Saignement.html&quot; title=&quot;Saignement&quot;&gt;saignement&lt;/a&gt;&lt;/i&gt; (DD 13)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Patron&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Protecteurs.html#ELEMENTS&quot; title=&quot;Les protecteurs de la sorci&#232;re&quot;&gt;&#233;l&#233;ments&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pendant le combat.&lt;/b&gt; La matrone &#226;g&#233;e troll attaque avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Colonne-De-Feu.html&quot; title=&quot;Colonne de feu&quot;&gt;colonne de feu&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Frappe-Douloureuse-De-Groupe.html&quot; title=&quot;Frappe douloureuse de groupe&quot;&gt;frappe douloureuse de groupe&lt;/a&gt;&lt;/i&gt;, puis elle adapte sa strat&#233;gie en fonction de ses adversaires, choisissant g&#233;n&#233;ralement les &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#MALEFICE&quot; title=&quot;La sorci&#232;re&quot;&gt;mal&#233;fices&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Malchance&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;malchance&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Mauvaisœil&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;mauvais œil&lt;/a&gt; et utilisant &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;partition-Des-Mal&#233;fices.html&quot; title=&quot;R&#233;partition des mal&#233;fices&quot;&gt;R&#233;partition des mal&#233;fices&lt;/a&gt; pour les appliquer aux deux ennemis que ces pouvoirs g&#234;neront le plus.
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 19, &lt;b&gt;Dex&lt;/b&gt; 14, &lt;b&gt;Con&lt;/b&gt; 27, &lt;b&gt;Int&lt;/b&gt; 16, &lt;b&gt;Sag&lt;/b&gt; 11, &lt;b&gt;Cha&lt;/b&gt; 8
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +9, &lt;b&gt;BMO&lt;/b&gt; +14, &lt;b&gt;DMD&lt;/b&gt; 26
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Dobjets-Merveilleux.html&quot; title=&quot;Cr&#233;ation d&amp;#39;objets merveilleux&quot;&gt;Cr&#233;ation d’objets merveilleux&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;l&#233;ment-Sup&#233;rieur.html&quot; title=&quot;&#201;l&#233;ment sup&#233;rieur&quot;&gt;&#201;cole &#233;l&#233;mentaire renforc&#233;e&lt;/a&gt; (feu), &lt;a class=&quot;pagelink&quot; href=&quot;&#201;l&#233;ment-Renforc&#233;.html&quot; title=&quot;&#201;l&#233;ment renforc&#233;&quot;&gt;&#201;l&#233;ment renforc&#233;&lt;/a&gt; (feu), &lt;a class=&quot;pagelink&quot; href=&quot;Magie-De-Guerre.html&quot; title=&quot;Magie de guerre&quot;&gt;Magie de guerre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;partition-Des-Mal&#233;fices.html&quot; title=&quot;R&#233;partition des mal&#233;fices&quot;&gt;R&#233;partition des mal&#233;fices&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-La-Volont&#233;-De-Fer.html&quot; title=&quot;Science de la volont&#233; de fer&quot;&gt;Science de la volont&#233; de fer&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l’initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; +11, &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; +7, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) +14, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature) +11, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +8, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +14, &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; +9, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +16, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; +8, &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; +8
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; abyssal, g&#233;ant, gobelin, orque
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#FAMILIER&quot; title=&quot;La sorci&#232;re&quot;&gt;familier de la sorci&#232;re&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Familiers.html&quot; title=&quot;Les familiers&quot;&gt;chauve-souris&lt;/a&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement de combat&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poudre-De-Disparition.html&quot; title=&quot;Poudre de disparition&quot;&gt;poudre de disparition&lt;/a&gt;&lt;/i&gt; ; &lt;b&gt; &#201;quipement divers&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-Darmure.html&quot; title=&quot;Bracelets d&amp;#39;armure&quot;&gt;bracelets d’armure +2&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-R&#233;sistance.html&quot; title=&quot;Cape de r&#233;sistance&quot;&gt;cape de r&#233;sistance +1&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Dintelligence.html&quot; title=&quot;Bandeau d&amp;#39;intelligence&quot;&gt;bandeau d’intelligence +4&lt;/a&gt;&lt;/i&gt;, 500 po
&lt;/div&gt;
